import pytest

from payments.currency import convert, format_money


def test_convert_same_currency_rounds_to_two_decimals():
    assert convert(2.3456, 'USD', 'USD') == 2.35


def test_convert_same_currency_rounds_down_to_two_decimals():
    assert convert(1.234, 'EUR', 'EUR') == 1.23


def test_format_money_zero_has_no_negative_sign():
    assert format_money(0, 'USD') == '$0.00'


def test_format_money_fraction_below_one_is_positive():
    assert format_money(0.5, 'USD') == '$0.50'


def test_format_money_negative_fraction():
    assert format_money(-0.5, 'USD') == '-$0.50'


def test_format_money_thousands_separator():
    assert format_money(1234.5, 'USD') == '$1,234.50'
